using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
namespace MyProjectManagement;
public static class StructuredChangeRequest {
 static string Required(JsonObject value,string key,int max,bool required=true){var text=J.S(value,key).Trim();J.Require(text.Length<=max&&(!required||text!=""),"Enter "+key+" (maximum "+max+" characters)",400);return text;}
 public static JsonObject DraftBody(JsonObject body,JsonObject mapping){var header=body["header"] as JsonObject??mapping["header"]!.AsObject();return new JsonObject{["projectId"]=J.S(body,"projectId"),["ctoId"]=J.S(body,"ctoId"),["pmId"]=J.S(body,"pmId"),["title"]=J.S(header,"externalNumber"),["description"]=J.S(body,"description")==""?"Module and form changes imported from Word":J.S(body,"description"),["reason"]=J.S(body,"reason")==""?"Word document import":J.S(body,"reason"),["header"]=header.DeepClone(),["points"]=(body["points"]??mapping["points"])!.DeepClone(),["amendmentResponses"]=body["amendmentResponses"]?.DeepClone()??new JsonArray()};}
 public static void Fields(JsonObject row,JsonObject revision,JsonObject body){var input=body["header"]!.AsObject();var header=new JsonObject();foreach(var (key,max,required) in new[]{("clientName",160,true),("projectName",240,true),("requestedBy",160,true),("externalNumber",140,true),("documentRevision",30,false),("date",10,true)})header[key]=Required(input,key,max,required);J.Day(J.S(header,"date"));var (number,suffix)=ChangeRequestWord.SplitNumber(J.S(header,"externalNumber"));header["externalNumber"]=number;if(suffix!="")header["documentRevision"]=suffix;J.Require(!J.S(header,"externalNumber").Any(char.IsControl),"Invalid change request number",400);var keyNumber=ChangeRequestWord.NumberKey(number);if(J.S(row,"externalNumberKey")!=""&&J.A(row,"revisions").Any(r=>J.N(r,"number")<J.N(revision,"number")||J.S(r,"submittedAt")!=""))J.Require(J.S(row,"externalNumberKey")==keyNumber,"Keep the original CR number; change the document revision instead",400);J.Require(J.S(header,"documentRevision")==""||Regex.IsMatch(J.S(header,"documentRevision"),"^[A-Za-z0-9][A-Za-z0-9._-]{0,29}$"),"Use a document revision such as 2.0 or A1",400);row["externalNumberKey"]=keyNumber;revision["header"]=header;
 var points=J.A(body,"points").ToList();J.Require(points.Count is >0 and <=50,"Enter 1–50 module/form rows",400);var result=new JsonArray();var ids=new HashSet<string>();foreach(var (point,i) in points.Select((p,i)=>(p,i))){string id=J.S(point,"id");if(id=="")id="P"+Guid.NewGuid().ToString("N")[..12];J.Require(Regex.IsMatch(id,"^P[A-Za-z0-9_-]{1,29}$")&&ids.Add(id),"Each form row needs a unique valid point ID",400);result.Add(new JsonObject{["id"]=id,["serial"]=J.S(point,"serial")==""?(i+1).ToString("00"):Required(point,"serial",40),["module"]=Required(point,"module",140),["formName"]=Required(point,"formName",240),["text"]=Required(point,"text",6000),["remarks"]=Required(point,"remarks",2000,false)});}revision["points"]=result;revision["pointReviewRequired"]=true;
 var allowed=PriorNotes(row).Select(n=>J.S(n,"key")).ToHashSet();var responses=J.A(body,"amendmentResponses").ToList();J.Require(responses.Count<=300&&responses.Select(r=>J.S(r,"key")).Distinct().Count()==responses.Count,"Invalid amendment responses",400);revision["amendmentResponses"]=new JsonArray(responses.Select(r=>{string key=Required(r,"key",80);J.Require(allowed.Contains(key),"Unknown previous review comment",400);return (JsonNode)new JsonObject{["key"]=key,["reply"]=Required(r,"reply",4000,false)};}).ToArray());}
 public static JsonArray PriorNotes(JsonObject row,string? reviewer=null){var notes=new JsonArray();int current=(int)J.N(ChangeRequests.Latest(row),"number");foreach(var revision in J.A(row,"revisions").Where(r=>J.N(r,"number")<current)){int ri=0;foreach(var review in J.A(revision,"reviews")){int index=ri++;if(reviewer is not null&&J.S(review,"by")!=reviewer&&J.S(review,"onBehalfOf")!=reviewer)continue;void Add(string suffix,string text,string point,string status=""){var p=J.A(revision,"points").FirstOrDefault(p=>J.S(p,"id")==point);notes.Add(new JsonObject{["pointStatus"]=status,["key"]="R"+J.N(revision,"number")+":"+index+":"+suffix,["revision"]=J.N(revision,"number"),["by"]=J.S(review,"by"),["stage"]=J.S(review,"stage"),["at"]=J.S(review,"at"),["decision"]=J.S(review,"decision"),["point"]=point,["text"]=text,["module"]=J.S(p,"module"),["formName"]=J.S(p,"formName"),["previousText"]=J.S(p,"text"),["documentId"]=J.S(revision,"documentId"),["meetingDate"]=J.S(review,"meetingDate")});}if(J.S(review,"comment")!="")Add("G",J.S(review,"comment"),"");int ci=0;foreach(var comment in J.A(review,"comments"))Add("C"+ci++,J.S(comment,"text"),J.S(comment,"point"),J.S(comment,"pointStatus"));}}return notes;}
 public static void Submit(JsonObject row){var revision=ChangeRequests.Latest(row);if(revision["header"] is not JsonObject)return;var previous=J.A(row,"revisions").Where(r=>J.N(r,"number")<J.N(revision,"number")).LastOrDefault();if(previous is null)return;var required=PriorNotes(row).Where(n=>J.N(n,"revision")==J.N(previous,"number")&&J.S(n,"decision")!="Approve"&&J.S(n,"pointStatus")!="Proceed");foreach(var note in required)J.Require(J.A(revision,"amendmentResponses").Any(r=>J.S(r,"key")==J.S(note,"key")&&J.S(r,"reply").Trim()!=""),"Respond to each previous amendment/clarification comment before resubmitting",400);}
 public static void Review(JsonObject row,string actor,JsonObject body){if(ChangeRequests.Latest(row)["header"] is JsonObject&&PriorNotes(row,actor).Count>0)J.Require(J.B(body,"checkedPrevious"),"Review your previous comments and the amendment responses before deciding",400);}
 public static bool Duplicate(JsonObject row,JsonObject other){if(J.S(row,"id")==J.S(other,"id")||J.S(row,"externalNumberKey")=="")return false;bool same=J.S(row,"externalNumberKey")==J.S(other,"externalNumberKey");return same&&(J.S(row,"projectId")==J.S(other,"projectId")||J.S(row,"customerId")!=""&&J.S(row,"customerId")==J.S(other,"customerId"));}
}
